static uint32_t aes_keywrap_unit(SEA_AES_KW_TESTLIST *testlist) {
    uint8_t cipher[48];
    uint8_t plain[48];
    uint32_t cipherlen, plainlen, tmp_err = SEA_SUCCESS;
    uint8_t *tmp;

    sea_memset_word((uint32_t *)cipher, 0U, 12U);
    sea_memset_word((uint32_t *)plain, 0U, 12U);

    AES_InitTypeDef cfg;
    aesProcessParameters pParas;
    cfg.encrypt_sel = AES_enCrypt;
    cfg.bitWideMode = testlist->bitWideMode;
    cfg.cryptMode = testlist->cryptMode;
    cfg.keyLocation = (aesKey_t *)testlist->kek;
    cfg.ivLocation = (aesIV_t *)0;
    cfg.keyWrapMode = testlist->keyWrapMode;
#ifndef SEA_HAL_FULL_TEST
    cfg.assignedAddress = (uint32_t)&AES_GCM_DMA_TEST[0];
#else
    cfg.runningMode = AES_GENERAL_MODE_EN;
#endif

    tmp_err = LL_AES_crypt_init(&pParas, (const AES_InitTypeDef *)&cfg);
    TEST_ASSERT_EQUAL_UINT(SEA_SUCCESS, tmp_err);
    tmp_err = LL_AES_key_wrap(&pParas, (const PlainData_t *)testlist->key, testlist->keylen, (CryptData_t *)cipher, &cipherlen);
    TEST_ASSERT_EQUAL_UINT(SEA_SUCCESS, tmp_err);
    (void)LL_AES_crypt_deinit();

    if ((testlist->ctlen != cipherlen) || (0 != memcmp((uint8_t *)cipher, (uint8_t *)testlist->ct, testlist->ctlen))) {
        printf("[log]++key wrap Fail!!!\n");

        printf("[log]++ctlen=%d, cipherlen=%d\n", testlist->ctlen, cipherlen);
        printf("[log]++cipher:\t");
        for (int i = 0; i < cipherlen; i++) {
            printf("%02X ", cipher[i]);
        }
        printf("\n");
        printf("[log]++    ct:\t");
        tmp = (uint8_t *)testlist->ct;
        for (int i = 0; i < cipherlen; i++) {
            printf("%02X ", tmp[i]);
        }
        printf("\n");
        return SEA_ERROR;
    }

    cfg.encrypt_sel = AES_deCrypt;
    cfg.bitWideMode = testlist->bitWideMode;
    cfg.cryptMode = testlist->cryptMode;
    cfg.keyLocation = (aesKey_t *)testlist->kek;
    cfg.ivLocation = (aesIV_t *)0;
    cfg.keyWrapMode = testlist->keyWrapMode;
#ifndef SEA_HAL_FULL_TEST
    cfg.assignedAddress = (uint32_t)&AES_GCM_DMA_TEST[0];
#else
    cfg.runningMode = AES_GENERAL_MODE_EN;
#endif

    tmp_err = LL_AES_crypt_init(&pParas, (const AES_InitTypeDef *)&cfg);
    TEST_ASSERT_EQUAL_UINT(SEA_SUCCESS, tmp_err);
    tmp_err = LL_AES_key_unwrap(&pParas, (const CryptData_t *)cipher, cipherlen, (PlainData_t *)plain, &plainlen);
    TEST_ASSERT_EQUAL_UINT(SEA_SUCCESS, tmp_err);
    (void)LL_AES_crypt_deinit();

    if ((testlist->keylen != plainlen) || (0 != memcmp((uint8_t *)plain, (uint8_t *)testlist->key, testlist->keylen))) {
        printf("[log]++key unwrap Fail!!!\n");

        printf("[log]++ptlen=%d, plainlen=%d\n", testlist->keylen, plainlen);
        printf("[log]++plain:\t");
        for (int i = 0; i < plainlen; i++) {
            printf("%02X ", plain[i]);
        }
        printf("\n");
        printf("[log]++   pt:\t");
        tmp = (uint8_t *)testlist->key;
        for (int i = 0; i < plainlen; i++) {
            printf("%02X ", tmp[i]);
        }
        printf("\n");
        return SEA_ERROR;
    }

    return SEA_SUCCESS;
}

void aes_keywrap_test(void) {
    uint32_t i, tmp_err = SEA_SUCCESS;
    AES_KernelTypeDef version = ((sea_update_stat()) ? AES_RUNNING_IN_CORE0 : AES_RUNNING_IN_CORE1);
    printf("</***********AES Key Wrap test Start*********\n");
    sea_init_all(version);

    for (i = 0U; i < (sizeof(testlist) / sizeof(testlist[0])); i++) {
        tmp_err = aes_keywrap_unit((SEA_AES_KW_TESTLIST *)testlist[i]);
        TEST_ASSERT_EQUAL_UINT(SEA_SUCCESS, tmp_err);
        printf("------[log]AES Key Wrap test %d run Pass------\n", i);
    }

    printf("***********AES Key Wrap test Finish*********/>\n");
}
